});

test('rule violations win over full columns', () => {
  const { TransitionError } = require('../index.js');
  const b = mk();
  b.setLimit('done', 1);
  b.add('x', 'done');
  b.add('a');
  b.allowMoves({ backlog: ['doing'] });
  assert.throws(() => b.move(2, 'done'), TransitionError);
});

